<fieldset class="ws-entry"><legend>Fiche</legend><label>Titre<input name="entries[<?=$key?>][<?=$n?>][title]" maxlength="190" value="<?=$h($item['title']??'')?>"></label><label>Description<textarea name="entries[<?=$key?>][<?=$n?>][body]" rows="4" maxlength="15000"><?=$h($item['body']??'')?></textarea></label><label>Catégorie / type<input name="entries[<?=$key?>][<?=$n?>][category]" maxlength="100" value="<?=$h($item['category']??'')?>"></label><label>Localisation / précision<input name="entries[<?=$key?>][<?=$n?>][location]" maxlength="190" value="<?=$h($item['location']??'')?>"></label><label>Image de la médiathèque<select name="entries[<?=$key?>][<?=$n?>][image]" data-media-select><option value="">Sans image</option><?php foreach($library as $num=>$image):?><option value="<?=$h($image['id'])?>" <?=($item['image']??'')===$image['id']?'selected':''?>>Image <?=count($library)-$num?> · <?=$h($image['created_at'])?></option><?php endforeach;?></select></label><img class="ws-media-preview" data-media-preview alt="Aperçu" <?php if(!empty($item['image'])):?>src="media.php?id=<?=$h($item['image'])?>&amp;preview=1"<?php else:?>hidden<?php endif;?>><label><input type="checkbox" name="entries[<?=$key?>][<?=$n?>][remove]" value="1"> Supprimer cette fiche</label></fieldset>